#include <stdio.h>

void div_mod(int a, int b, int *q, int *r) {
    int quotient = a / b;
    int remainder = a % b;
    if (remainder < 0) {
        remainder += b;
        quotient--;
    }
    *q = quotient;
    *r = remainder;
}

int main(void) {
    int a, b;
    while (scanf("%d %d", &a, &b) == 2) {
        int q, r;
        div_mod(a, b, &q, &r);
        printf("%d %d\n", q, r);
    }
    return 0;
}

