additionalExercises.referenceSolution:
#include <stdio.h>

void min_max(const int *a, int n, int *min, int *max) {
    int lo = a[0], hi = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < lo) {
            lo = a[i];
        }
        if (a[i] > hi) {
            hi = a[i];
        }
    }
    if (min != NULL) {
        *min = lo;
    }
    if (max != NULL) {
        *max = hi;
    }
}

int main(void) {
    int a[1000];
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int lo = 0, hi = 0;
    min_max(a, n, &lo, &hi);
    printf("%d %d\n", lo, hi);
    int only_max = 0;
    min_max(a, n, NULL, &only_max);
    int only_min = 0;
    min_max(a, n, &only_min, NULL);
    printf("%d %d\n", only_min, only_max);
    return 0;
}

