#include <stdio.h>
#include <ctype.h>

bool parse_time(const char *s, int *minutes) {
    for (int i = 0; i < 5; i++) {
        if (s[i] == '\0') {
            return false;
        }
    }
    if (s[5] != '\0' || s[2] != ':') {
        return false;
    }
    if (!isdigit(s[0]) || !isdigit(s[1]) || !isdigit(s[3]) || !isdigit(s[4])) {
        return false;
    }
    int h = (s[0] - '0') * 10 + (s[1] - '0');
    int m = (s[3] - '0') * 10 + (s[4] - '0');
    if (h > 23 || m > 59) {
        return false;
    }
    *minutes = h * 60 + m;
    return true;
}

int main(void) {
    char word[21];
    while (scanf("%20s", word) == 1) {
        int m;
        if (parse_time(word, &m)) {
            printf("%d\n", m);
        } else {
            printf("ошибка\n");
        }
    }
    return 0;
}

