#include <stdio.h>

void stats(const int *a, int n, int *sum, int *even) {
    *sum = 0;
    *even = 0;
    for (int i = 0; i < n; i++) {
        *sum += a[i];
        if (a[i] % 2 == 0) {
            (*even)++;
        }
    }
}

int main(void) {
    int a[4] = {3, 4, 6, 7};
    int s, e;
    stats(a, 4, &s, &e);
    printf("%d %d\n", s, e);
    return 0;
}
